wc -l /home/eslam/Downloads/TTFolder/quickflow-claude-loops/loops/backend-dev/runs/002-us-tags/phase-01-build.log; python3 -c "
import glob,xml.etree.ElementTree as E
t=f=e=s=0
for p in glob.glob('target/surefire-reports/TEST-*.xml'):
    r=E.parse(p).getroot(); t+=int(r.get('tests'));f+=int(r.get('failures'));e+=int(r.get('errors'));s+=int(r.get('skipped'))
    for c in r.iter('testcase'):
        for k in c:
            if k.tag in('failure','error'): print(c.get('classname'),c.get('name'),(k.get('message') or '')[:300])
print('tests',t,'fail',f,'err',e,'skip',s)
"; ls -la target/surefire-reports | head -3; grep -o 'line-rate="[^"]*"' target/site/jacoco/jacoco.xml 2>/dev/null | head -1
